function generate(rand, size) {
  const maxBits = size === 'large' ? 31 : 8;
  const minBits = size === 'large' ? 20 : 1;
  const bits = minBits + Math.floor(rand() * (maxBits - minBits + 1));
  const r = rand();
  if (r < 0.3) {
    // Any number with this many bits.
    const low = 2 ** (bits - 1);
    return [low + Math.floor(rand() * low)];
  }
  // An alternating number with this many bits, sometimes with one bit flipped.
  let n = 0;
  for (let i = 0; i < bits; i++) n = n * 2 + (i % 2 === 0 ? 1 : 0);
  if (r < 0.65 && bits > 1) {
    const flip = Math.floor(rand() * (bits - 1));
    n ^= 1 << flip;
  }
  return [n];
}
